// Generates the CSS token files from tokens.json and checks colour contrast.
//   node design-system/build.mjs
// Outputs (do not edit by hand):
//   hi-daniel.theme.css  — Tailwind CSS v4 (@import it after "tailwindcss")
//   hi-daniel.tokens.css — plain CSS custom properties (--hd-*) for any other stack
// Exits with code 1 if a required text/background pair drops below WCAG AA.

import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

const dir = fileURLToPath(new URL(".", import.meta.url));
const tokens = JSON.parse(readFileSync(dir + "tokens.json", "utf8"));
const { color } = tokens;

const resolve = (value) =>
  value.replace(/\{([\w-]+)\}/g, (_, name) => {
    if (!(name in color)) throw new Error(`Unknown colour reference {${name}}`);
    return color[name];
  });

const banner = `/* GENERATED by design-system/build.mjs from tokens.json (v${tokens.version}) — do not edit by hand. */\n`;
const block = (selector, lines) => `${selector} {\n${lines.map((l) => `  ${l}`).join("\n")}\n}\n`;
const entries = (obj) => Object.entries(obj);

const semanticVars = (mode) => entries(tokens.semantic[mode]).map(([k, v]) => `--hd-${k}: ${resolve(v)};`);
const darkSelector = ".hd-dark,\n[data-theme=\"dark\"]";

/* ---------- Tailwind v4 theme ---------- */
const theme = [];
for (const [k, v] of entries(color)) if (k !== "white") theme.push(`--color-${k}: ${v};`);
for (const [k, v] of entries(tokens.product)) theme.push(`--color-product-${k}: ${resolve(v)};`);
theme.push(`--font-sans: ${tokens.font.sans};`);
for (const [k, t] of entries(tokens.text)) {
  theme.push(`--text-${k}: ${t.size};`);
  theme.push(`--text-${k}--line-height: ${t.lineHeight};`);
  theme.push(`--text-${k}--letter-spacing: ${t.letterSpacing};`);
  theme.push(`--text-${k}--font-weight: ${t.weight};`);
}
for (const [k, v] of entries(tokens.radius)) theme.push(`--radius-${k}: ${v};`);
for (const [k, v] of entries(tokens.shadow)) theme.push(`--shadow-${k}: ${v};`);
for (const [k, v] of entries(tokens.ease)) theme.push(`--ease-${k}: ${v};`);

// Semantic colours point at runtime variables so `.hd-dark` can switch them per section.
const inline = entries(tokens.semantic.light).map(([k]) => `--color-${k}: var(--hd-${k});`);

const runtime = [
  ...semanticVars("light"),
  ...entries(tokens.gradient).map(([k, v]) => `--hd-gradient-${k}: ${v};`),
  ...entries(tokens.duration).map(([k, v]) => `--hd-duration-${k}: ${v};`),
];

writeFileSync(
  dir + "hi-daniel.theme.css",
  banner +
    block("@theme", theme) +
    "\n" +
    block("@theme inline", inline) +
    "\n" +
    block(":root", runtime) +
    "\n" +
    block(darkSelector, semanticVars("dark")),
);

/* ---------- Plain CSS variables ---------- */
const plain = [
  ...entries(color).map(([k, v]) => `--hd-${k}: ${v};`),
  ...entries(tokens.product).map(([k, v]) => `--hd-product-${k}: ${resolve(v)};`),
  `--hd-font-sans: ${tokens.font.sans};`,
  ...entries(tokens.text).flatMap(([k, t]) => [
    `--hd-text-${k}: ${t.size};`,
    `--hd-text-${k}-line-height: ${t.lineHeight};`,
    `--hd-text-${k}-letter-spacing: ${t.letterSpacing};`,
    `--hd-text-${k}-weight: ${t.weight};`,
  ]),
  ...entries(tokens.radius).map(([k, v]) => `--hd-radius-${k}: ${v};`),
  ...entries(tokens.shadow).map(([k, v]) => `--hd-shadow-${k}: ${v};`),
  ...entries(tokens.ease).map(([k, v]) => `--hd-ease-${k}: ${v};`),
  ...runtime,
];
writeFileSync(dir + "hi-daniel.tokens.css", banner + block(":root", plain) + "\n" + block(darkSelector, semanticVars("dark")));

/* ---------- Contrast check (WCAG 2.x) ---------- */
const rgba = (css) => {
  const hex = css.match(/^#([0-9a-f]{6})$/i);
  if (hex) return [0, 2, 4].map((i) => parseInt(hex[1].slice(i, i + 2), 16)).concat(1);
  const fn = css.match(/^rgb\((\d+) (\d+) (\d+)(?: \/ ([\d.]+))?\)$/);
  if (fn) return [+fn[1], +fn[2], +fn[3], fn[4] === undefined ? 1 : +fn[4]];
  throw new Error(`Cannot parse colour ${css}`);
};
const over = (fg, bg) => fg.slice(0, 3).map((c, i) => c * fg[3] + bg[i] * (1 - fg[3]));
const luminance = (rgb) =>
  rgb
    .map((c) => c / 255)
    .map((c) => (c <= 0.03928 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4))
    .reduce((sum, c, i) => sum + c * [0.2126, 0.7152, 0.0722][i], 0);
const contrast = (fgCss, bgCss) => {
  const bg = rgba(bgCss).slice(0, 3);
  const [a, b] = [luminance(over(rgba(fgCss), bg)), luminance(bg)].sort((x, y) => y - x);
  return (a + 0.05) / (b + 0.05);
};

// [foreground, background, minimum ratio, note]. A note marks a documented exception (warn only).
const pairs = [
  ["fg", "canvas", 4.5],
  ["fg-muted", "surface", 4.5],
  ["fg-muted", "canvas", 4.5],
  ["link", "surface", 4.5],
  ["success", "surface", 4.5],
  ["warning", "surface", 4.5],
  ["danger", "surface", 4.5],
  ["info", "surface", 4.5],
  ["on-secondary", "secondary", 4.5],
  ["fg-subtle", "surface", 4.5, "decorative / ≥24px only"],
  ["on-primary", "primary", 4.5, "brand CTA exception — see DESIGN.md §5"],
];

let failed = false;
for (const mode of ["light", "dark"]) {
  const s = Object.fromEntries(entries(tokens.semantic[mode]).map(([k, v]) => [k, resolve(v)]));
  console.log(`\n${mode.toUpperCase()}`);
  for (const [fg, bg, min, note] of pairs) {
    const ratio = contrast(s[fg], s[bg]);
    const ok = ratio >= min;
    if (!ok && !note) failed = true;
    const mark = ok ? "PASS" : note ? "WARN" : "FAIL";
    console.log(`  ${mark}  ${ratio.toFixed(2).padStart(5)}:1  ${fg} on ${bg}${!ok && note ? `  (${note})` : ""}`);
  }
}
console.log("\nWrote hi-daniel.theme.css and hi-daniel.tokens.css");
if (failed) process.exit(1);
